#include <iostream>
#include <iterator>
#include <string>

int main() {
    std::istream_iterator<std::string> str_it(std::cin); // Initialize iterator from input stream
    std::istream_iterator<std::string> end_it; // Default-constructed end iterator

    while (str_it != end_it) {
        std::string token = *str_it; // Access current token
        // Process token (e.g., store, analyze, or transform)
        std::cout << "Read token: " << token << std::endl;
        ++str_it; // Advance iterator to next token
    }
    return 0;
}
